import * as THREE from 'three';
import {CAFE_MENU as M} from './cafe-config.js';
export function buildCafeRoom(def,kit,progress){
 const {root,box,sphere,cylinder,label}=kit,named=(o,n)=>(o.name='cafe.'+n,o),group=n=>{const g=named(new THREE.Group(),n);root.add(g);return g;};
 box(10.6,.34,9.6,'#b18a62',0,-.18,.25,.14);for(let i=0;i<12;i++)box(.86,.045,9.42,i%2?'#e9cd9e':'#f2ddb7',-4.79+i*.87,.01,.25,.008);
 box(10.6,3.12,.18,'#e4c8a1',0,1.56,-4.47,.04);box(10.6,.32,.21,'#749d8b',0,.22,-4.35,.03);for(const x of [-5.22,5.22])box(.18,.58,9.6,'#bf9a72',x,.3,.25,.035);box(10.6,.15,.25,'#fff1cd',0,3.17,-4.47,.03);
 label('밀구름',0,2.59,-4.32,2.55,'#fff5d6','#608977');label('갓 구운 빵과 따뜻한 한 잔',0,1.96,-4.30,3.65,'#754c30','#e4c8a1');
 for(const x of [-3.55,3.55]){box(2.1,1.55,.15,'#fff4dd',x,2.2,-4.3,.07);box(1.88,1.32,.04,'#b8d5c5',x,2.2,-4.19,.04);box(.07,1.37,.06,'#fff4dd',x,2.2,-4.14,.009);box(1.94,.07,.07,'#fff4dd',x,2.2,-4.14,.009);for(const dx of [-.9,.9])box(.22,1.5,.14,'#dfa991',x+dx,2.21,-4.1,.045);box(2.28,.12,.4,'#e4b878',x,1.43,-4.06,.04);}
 // The original footprint is preserved: all detail lives on the counters or outside walking lanes.
 const work=group('workbench');work.name='bakeryCafe.workbench';box(3.4,.98,1.4,'#719883',0,.53,-1.4,.09,work);box(3.58,.14,1.52,'#edc88c',0,1.08,-1.4,.06,work);for(const x of [-1.08,0,1.08]){box(.96,.63,.05,'#86aa94',x,.61,-.665,.025,work);box(.25,.055,.08,'#d8b573',x,.7,-.62,.014,work);}label('반죽 작업대',-.55,.63,-.60,1.6,'#fff5d5','#86aa94',work);
 box(1.20,.032,.85,'#f8e5bc',-.5,1.17,-1.4,.06,work);const pin=cylinder(.07,.07,.70,'#bc8b52',-.42,1.26,-1.62,work);pin.rotation.z=Math.PI/2;for(const x of [-.88,.04]){const h=cylinder(.035,.035,.22,'#855c36',x,1.26,-1.62,work);h.rotation.z=Math.PI/2;}
 cylinder(.23,.16,.26,'#d7a58c',-1.30,1.29,-1.5,work);sphere(.19,'#fff0d1',-1.30,1.42,-1.5,1,.22,1,work);box(.62,.06,.48,'#f5e5c5',1.02,1.19,-1.37,.035,work);box(.34,.32,.3,'#638f81',1.15,1.35,-1.69,.045,work);box(.3,.16,.04,'#273e39',1.15,1.45,-1.51,.012,work);for(let i=0;i<3;i++)box(.055,.026,.045,'#eecb8b',.99+i*.08,1.34,-1.51,.008,work);label('주문 받는 곳',1.02,.67,-.60,1.45,'#fff6dc','#86aa94',work);
 const oven=group('oven');box(1.1,1.7,2,'#71958a',-3.75,.88,-2.4,.10,oven);box(1.15,.84,.12,'#425f56',-3.75,.92,-1.34,.055,oven);const glow=named(box(.82,.53,.055,'#624a32',-3.75,.94,-1.26,.055,oven),'oven-window');const handle=named(box(.7,.07,.13,'#c1a469',-3.75,1.32,-1.22,.02,oven),'oven-handle');for(const x of [-4.05,-3.45]){const knob=cylinder(.075,.075,.06,'#e3c98c',x,1.62,-1.33,oven);knob.rotation.x=Math.PI/2;}label('오븐',-3.75,1.96,-1.8,1.1);const gauge=named(cylinder(.13,.13,.06,'#f4e3bb',-3.75,1.65,-1.33,oven),'oven-upgrade-gauge');gauge.rotation.x=Math.PI/2;gauge.visible=false;
 const door=group('oven-door');door.position.set(-3.75,.48,-1.24);door.attach(glow);door.attach(handle);box(.90,.035,.55,'#b69a69',-3.75,.71,-1.47,.008,oven);
 const ovenFood=group('oven-food'),doughFood=group('dough-food'),rackFood=group('rack-food'),drinkFood=group('drink-food');
 // A low glass display along the original right-hand shelf footprint.
 box(1.15,.56,2.04,'#bd8653',3.75,.31,-2.4,.06);for(const x of [3.2,4.3])for(const z of [-3.4,-1.4])box(.045,1.16,.045,'#bd955d',x,1.10,z,.009);box(1.25,.07,2.12,'#edc890',3.75,.76,-2.4,.025);const glassTop=named(box(1.25,.055,2.12,'#d5e6d6',3.75,1.7,-2.4,.015),'display-glass-top');glassTop.material=new THREE.MeshStandardMaterial({color:'#d6e7d7',transparent:true,opacity:.10,roughness:.12,depthWrite:false});for(const x of [3.15,4.35])box(.045,.065,2.15,'#c79b62',x,1.71,-2.4,.01);for(const z of [-3.43,-1.37])box(1.23,.065,.045,'#c79b62',3.75,1.71,z,.01);const glass=new THREE.Mesh(new THREE.BoxGeometry(1.16,.86,.015),new THREE.MeshStandardMaterial({color:'#d6e7d7',transparent:true,opacity:.15,roughness:.12,depthWrite:false}));glass.position.set(3.75,1.22,-1.38);root.add(glass);named(glass,'display-glass');const shelf=named(box(1.18,.05,2.04,'#f1d8aa',3.75,1.19,-2.4,.015),'display-upgrade-shelf');shelf.material=new THREE.MeshStandardMaterial({color:'#e4efdf',transparent:true,opacity:.18,roughness:.18,depthWrite:false});shelf.visible=false;label('오늘의 빵',3.75,1.97,-2.0,1.5);
 const drink=group('drink-station');box(1.12,.92,1.10,'#9d7955',-3.75,.49,-.10,.07,drink);box(1.24,.10,1.19,'#e1bd84',-3.75,1.0,-.10,.04,drink);box(.67,.60,.56,'#b7c5ac',-3.81,1.34,-.32,.08,drink);box(.46,.3,.05,'#496b5d',-3.81,1.38,-.015,.03,drink);const spout=cylinder(.032,.032,.18,'#bdaf8b',-3.80,1.20,.08,drink);box(.80,.08,.48,'#71563c',-3.75,1.10,.22,.04,drink);label('음료',-3.75,.59,.48,1.1,'#fff1d0','#9d7955',drink);
 // Pots, flour sack, linen, stacked saucers and bread tongs add scale without blocking a path.
 for(let i=0;i<3;i++)cylinder(.16,.16,.025,'#f6ead1',-4.1,1.09+i*.032,.2,drink);for(const x of [-4.6,4.65]){cylinder(.23,.17,.40,'#c88766',x,.24,-3.65);for(let i=0;i<3;i++)sphere(.23,'#779b69',x+(i-1)*.12,.65+Math.sin(i)*.12,-3.65,.7,1.3,.7);}
 const cozy=group('cozy-corner');cozy.visible=false;for(const x of [-3.3,3.3]){cylinder(.6,.54,.1,'#d6a66d',x,.86,2.2);cylinder(.12,.22,.8,'#95704d',x,.42,2.2);box(.8,.12,.7,'#8ca389',x,.5,3.6,.07);box(.8,.54,.1,'#8ca389',x,.82,3.92,.04);for(const dx of [-.28,.28])for(const dz of [-.23,.23])box(.07,.46,.07,'#95704d',x+dx,.24,3.6+dz,.015);cylinder(.31,.31,.025,'#f5ecd4',x,.93,2.2);box(.72,.045,.48,'#d4b4a0',x,.94,2.2,.035,cozy);box(.62,.14,.47,'#d5a28d',x,.64,3.6,.1,cozy);cylinder(.08,.10,.21,'#e2bc7d',x+.3,1.07,2.03,cozy);sphere(.12,'#ddb1a3',x+.3,1.24,2.03,1,.7,1,cozy);}
 box(2.55,.026,1.65,'#7d9f84',0,.06,3.36,.14);
 function clear(g){for(const c of [...g.children]){c.traverse(o=>o.geometry?.dispose());g.remove(c);}}
 function food(id,x,y,z,parent,scale=1){const g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(scale);g.name='food.'+id;parent.add(g);if(id==='milkRoll'){sphere(.27,'#dfaa61',0,.14,0,1.3,.64,.82,g);for(const dx of [-.13,0,.13]){const cut=box(.028,.015,.27,'#f3d5a0',dx,.283,0,.01,g);cut.rotation.z=-.22;}}
  else if(id==='croissant'){for(let i=0;i<5;i++){const a=(i-2)*.5,part=sphere(.15,'#d99b4f',Math.sin(a)*.24,.11,Math.cos(a)*.15-.08,1.15-i%2*.1,.70,1,g);part.rotation.y=-a;}for(const x of [-.28,.28])sphere(.09,'#c5873f',x,.07,-.10,1,.7,1,g);}
  else if(id==='miniCake'){cylinder(.24,.26,.23,'#d3a36d',0,.12,0,g);cylinder(.25,.24,.085,'#fff1d8',0,.27,0,g);for(const x of [-.11,.11])sphere(.074,'#cc7470',x,.345,0,.8,1.1,.8,g);}
  else {cylinder(.145,.11,.22,id==='herbTea'?'#aac6a1':'#cf9c85',0,.12,0,g);cylinder(.12,.12,.018,id==='herbTea'?'#8e9c56':'#815334',0,.238,0,g);const h=new THREE.Mesh(new THREE.TorusGeometry(.07,.022,6,12),kit.mat(id==='herbTea'?'#aac6a1':'#cf9c85'));h.position.set(.16,.14,0);g.add(h);cylinder(.21,.21,.02,'#f8e9ca',0,.016,0,g);}return g;}
 const steam=group('steam');for(let i=0;i<4;i++){const p=sphere(.05,'#fff0cc',-3.80+(i%2)*.12,1.48+i*.1,.15,.65,1.7,.65,steam);p.material=p.material.clone();p.material.transparent=true;p.material.opacity=.40;p.material.depthWrite=false;}steam.visible=false;
 let current=progress.village.cafe,signature='',celebration=0,doorOpen=0,foldPress=0;
 function update(v){current=v.cafe;const s=current;if(!s)return;const sig=JSON.stringify([s.stock,s.dough?.recipeId,s.dough?.folds,s.oven?.recipeId,s.drink?.recipeId,s.upgrades]);if(sig===signature)return;signature=sig;clear(ovenFood);clear(doughFood);clear(rackFood);clear(drinkFood);handle.material=kit.mat(s.upgrades.warmOven?'#e8bb50':'#c1a469');gauge.visible=s.upgrades.warmOven;shelf.visible=s.upgrades.wideDisplay;cozy.visible=s.upgrades.cozyCorner;
  if(s.dough){const f=sphere(.30,'#f6ddaf',-.45,1.24,-1.20,1.2,.35+s.dough.folds*.045,.85,doughFood);f.name='cafe.kneading-dough';}if(s.oven){food(s.oven.recipeId,-3.75,.85,-1.25,ovenFood,.68);glow.material=kit.mat('#d79840');}else glow.material=kit.mat('#624a32');
  let i=0;for(const id of ['milkRoll','croissant','miniCake'])for(let j=0;j<s.stock[id];j++,i++){const row=i<3?0:1,place=i<3?i:i-3;cylinder(.28,.28,.023,'#f9edcf',3.75,row?1.235:.812,-3.0+place*.60,rackFood);food(id,3.75,row?1.25:.83,-3+place*.60,rackFood,.76);}let k=0;for(const id of ['herbTea','cocoa'])for(let j=0;j<s.stock[id];j++,k++)food(id,-3.52+k*.32,1.1,.20,drinkFood,.82);if(s.drink)food(s.drink.recipeId,-3.8,1.1,.13,drinkFood,.75);steam.visible=!!s.drink;
 }
 function tick(dt,time,reduced=false){if(!current||reduced)return;const t=time/1000;doorOpen=Math.max(0,doorOpen-dt);foldPress=Math.max(0,foldPress-dt*3);door.rotation.x=-Math.sin(Math.min(1,doorOpen/.65)*Math.PI)*.6;if(current.dough){const d=doughFood.children[0];if(d)d.scale.y=.35+current.dough.folds*.045+Math.sin(t*4)*.02-foldPress*.12;}steam.children.forEach((p,i)=>{p.position.y=1.4+(t*.23+i*.14)%.65;});if(celebration>0){celebration-=dt;work.rotation.z=Math.sin(celebration*15)*.006;}else work.rotation.z=0;}
 root.userData.environment={kind:'bakeryCafe',fixtures:['workbench','oven','display-case','drink-station','cafe-tables','cash-register']};update(progress.village);return {update,tick,work(a){if(['CAFE_LOAD_OVEN','CAFE_DISPLAY_BREAD'].includes(a.type))doorOpen=.65;if(a.type==='CAFE_FOLD')foldPress=1;},celebrate(){celebration=.65;},food,snapshot(){return {stock:{...current.stock},warmOven:gauge.visible,wideDisplay:shelf.visible,cozyCorner:cozy.visible};}};
}
